function styleFor(l){let tiles,attrib;if(l.basemap==='satellite'){tiles=['https://services.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}'];attrib='Satellite basemap · Esri, Maxar, Earthstar Geographics and GIS user community';}else if(l.basemap==='weather'){tiles=[`https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/MODIS_Terra_CorrectedReflectance_TrueColor/default/${l.date}/GoogleMapsCompatible_Level9/{z}/{y}/{x}.jpg`];attrib=`NASA GIBS · MODIS Terra daily true-color · ${l.date} UTC (composite)`;}else{tiles=['https://tile.openstreetmap.org/{z}/{x}/{y}.png'];attrib='© OpenStreetMap contributors';}l.attribution=attrib;return {version:8,sources:{base:{type:'raster',tiles,tileSize:256,maxzoom:l.basemap==='weather'?9:19,attribution:attrib}},layers:[{id:'base',type:'raster',source:'base',paint:{'raster-saturation':l.look==='dark'?-.85:l.look==='contrast'?.1:0,'raster-brightness-max':l.look==='dark'?.45:1,'raster-contrast':l.look==='contrast'?.3:0}}],projection:{type:l.projection||'mercator'}};}
