function getMedia(l){if(!l.src)return null;if(media.has(l.id))return media.get(l.id);let el;if(['image','logo'].includes(l.type)){el=new Image();el.onload=()=>draw();el.src=l.src;}else{el=document.createElement(l.type==='audio'?'audio':'video');el.src=l.src;el.preload='auto';el.playsInline=true;el.addEventListener('loadeddata',()=>{if(!playing)draw();});el.addEventListener('seeked',()=>{if(!playing)draw();});if(audioContext){const node=audioContext.createMediaElementSource(el),gain=audioContext.createGain();node.connect(gain);gain.connect(audioContext.destination);el._gain=gain;gain.connect(destination);}}media.set(l.id,el);return el;}
