function seek(t){time=M.clamp(t,0,project.duration);synchronizeMedia();draw();}
function tick(now){if(playing){if(lastFrame)time+=(now-lastFrame)/1000;if(time>=project.duration){time=project.duration;playing=false;$('#play').textContent='▶ Play';synchronizeMedia();}}lastFrame=now;if(playing){synchronizeMedia();draw();}requestAnimationFrame(tick);}
function togglePlay(){if(exporting)return;connectAudio();playing=!playing;if(playing&&time>=project.duration)time=0;lastFrame=0;$('#play').textContent=playing?'Ⅱ Pause':'▶ Play';}
function eventXY(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*project.width/r.width,y:(e.clientY-r.top)*project.height/r.height};}
canvas.onpointerdown=e=>{if(exporting||$('#navigate').checked)return;const p=eventXY(e);const hit=project.layers.find(l=>M.active(l,time)&&!['map','audio','geometry','marker'].includes(l.type)&&(l.type==='rings'?Math.hypot(p.x-l.x,p.y-l.y)<l.reach:p.x>=l.x-8&&p.y>=l.y-8&&p.x<=l.x+l.w+8&&p.y<=l.y+l.h+8));if(!hit)return;choose(hit.id,e.shiftKey);if(hit.locked)return;checkpoint();drag={kind:'preview',l:hit,resize:Math.abs(p.x-hit.x-hit.w)<18&&Math.abs(p.y-hit.y-hit.h)<18,p,items:project.layers.filter(l=>selected.has(l.id)&&!l.locked).map(l=>({l,x:l.x,y:l.y,w:l.w,h:l.h}))};canvas.setPointerCapture(e.pointerId);};
