  time=0;lastFrame=0;recorder.start(1000);playing=true;$('#play').textContent='Rendering';status('Rendering in real time. Keep the app visible until export finishes.');
  await new Promise(resolve=>{const poll=setInterval(()=>{if(!playing||recorder.state==='inactive'){clearInterval(poll);resolve();}},100);});
  if(recorder.state!=='inactive')recorder.stop();const blob=await result;playing=false;synchronizeMedia();status(window.desktop?'Encoding H.264 MP4…':'Saving WebM preview…');
