project.layers=[M.layer('logo','Brand',{x:1650,y:60,w:210,h:80,text:'RAWS',fontSize:46,color:'#9af0c4'}),M.layer('text','Main headline',{x:80,y:850,w:1740,h:120,text:'GEOGRAPHY IN MOTION',fontSize:76}),M.layer('shape','Section banner',{x:80,y:755,w:580,h:80,color:'#246d58',text:'YOUR STORY. EVERY LAYER.',fontSize:30}),M.layer('marker','New York marker',{mapId:starterMap.id,lng:-74.006,lat:40.7128,markerSize:9,text:'NEW YORK',fontSize:27,x:0,y:0,w:300,h:80,color:'#9af0c4'}),starterMap];
